def summarize(rs,key,method,conv=None):
 ms=[r[key] for r in rs] if key else rs;n=len(ms);o=dict(method=method,n=n,PF_converged=conv,full_feasible=sum(r['all_tested_constraints_pass'] for r in ms))
 keys=['max_p_residual_mw','max_q_residual_mvar','max_generator_component_violation_mw_or_mvar','max_voltage_violation_pu','max_angle_violation_deg','cost_error_percent','voltage_mae_pu','angle_mae_deg','pg_mae_mw','qg_mae_mvar']
 for k in keys:
  v=np.array([r[k] for r in ms]);o[k]=dict(median=float(np.median(v)),p95=float(np.percentile(v,95)),worst=float(np.max(v)))
 o['violation_counts']=dict(balance=sum(r['max_p_residual_mw']>1e-3 or r['max_q_residual_mvar']>1e-3 for r in ms),generator=sum(r['max_generator_component_violation_mw_or_mvar']>1e-3 for r in ms),voltage=sum(r['max_voltage_violation_pu']>1e-4 for r in ms),angle=sum(r['max_angle_violation_deg']>1e-3 for r in ms),thermal='N/A; all original RATE_A=0')
 feasible=[r['cost_error_percent'] for r in ms if r['all_tested_constraints_pass']];o['feasible_cost_error_percent_median']=float(np.median(feasible)) if feasible else None
 return o

